/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: video, videoResponses, json, renderVideos
 * Tests
 *   - lists Videos as wide cards and loads the next page from the issued cursor
 *   - explains an empty Videos page
 *   - offers a retry when Videos cannot load
 *   - retains loaded Videos when loading more fails and retries the same cursor
 *   - rejects a malformed mixed Audio and Video response instead of showing Audio cards
 *   - preserves rendered Videos when refresh fails and explains how to retry
 * @end-catalog */

import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { act, render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { MemoryRouter } from 'react-router';

import { browserSessionQueryKey } from '../../api/session';
import { listenerVideosQueryKey } from '../../api/listenerVideos';
import { VideosPage } from './VideosPage';

const video = (index: number) => ({
  contentType: 'audioTrack',
  id: `${String(index).padStart(2, '0')}23456789abcdef01234567`,
  title: `Lorem Video ${index}`,
  artworkUrl: `/video-${index}.jpg`,
  artistNames: ['Dolor Ensemble'],
  albumId: null,
  albumTitle: null,
  duration: '04:14',
  mediaType: 'video',
  streamUrl: `/content/mediaTrack/stream/${String(index).padStart(2, '0')}23456789abcdef01234567`
});

/** Answers Videos reads in order while other card reads (capabilities, share state) get an empty object. */
const videoResponses = (...responses: Array<() => Response>) => {
  const reads: string[] = [];
  const fetchMock = vi.fn(async (input: RequestInfo | URL) => {
    const url = String(input);
    if (!url.includes('/api/listener/v1/videos')) return json({});
    reads.push(url);
    return (responses.shift() ?? responses.at(-1) ?? (() => json({ items: [], nextCursor: null })))();
  });
  vi.stubGlobal('fetch', fetchMock);
  return reads;
};

const json = (body: unknown, status = 200) => new Response(JSON.stringify(body), {
  status,
  headers: { 'Content-Type': 'application/json' }
});

/** Renders Videos signed out with deterministic query behavior. */
const renderVideos = () => {
  const queryClient = new QueryClient({ defaultOptions: { queries: { retry: false } } });
  queryClient.setQueryData(browserSessionQueryKey, null);
  const view = render(
    <QueryClientProvider client={queryClient}>
      <MemoryRouter><VideosPage /></MemoryRouter>
    </QueryClientProvider>
  );
  return { ...view, queryClient };
};

afterEach(() => {
  vi.restoreAllMocks();
});

test('lists Videos as wide cards and loads the next page from the issued cursor', async () => {
  const user = userEvent.setup();
  const reads = videoResponses(
    () => json({ items: [video(1), video(2)], nextCursor: '0223456789abcdef01234567' }),
    () => json({ items: [video(3)], nextCursor: null })
  );
  const { container } = renderVideos();

  expect(await screen.findByRole('heading', { level: 1, name: 'Video' })).toBeInTheDocument();
  const grid = await screen.findByRole('region', { name: 'Video' });
  expect(within(grid).getAllByRole('listitem')).toHaveLength(2);
  expect(container.querySelectorAll('[data-presentation="grid"] [class*="wideArtwork"]')).toHaveLength(2);
  expect(within(grid).getByRole('button', { name: /Lorem Video 1/ })).toBeInTheDocument();
  expect(reads[0]).toContain('/api/listener/v1/videos?limit=24');

  await user.click(screen.getByRole('button', { name: 'Load more' }));

  expect(await within(grid).findByRole('button', { name: /Lorem Video 3/ })).toBeInTheDocument();
  expect(reads[1]).toContain('cursor=0223456789abcdef01234567');
  expect(screen.queryByRole('button', { name: 'Load more' })).not.toBeInTheDocument();
});

test('explains an empty Videos page', async () => {
  videoResponses(() => json({ items: [], nextCursor: null }));
  renderVideos();

  expect(await screen.findByText('No music is available in this section yet.')).toBeInTheDocument();
  expect(screen.queryByRole('listitem')).not.toBeInTheDocument();
});

test('offers a retry when Videos cannot load', async () => {
  const user = userEvent.setup();
  videoResponses(
    () => new Response(null, { status: 503 }),
    () => json({ items: [video(1)], nextCursor: null })
  );
  renderVideos();

  await user.click(await screen.findByRole('button', { name: 'Try again' }));

  expect(await screen.findByRole('button', { name: /Lorem Video 1/ })).toBeInTheDocument();
});

test('retains loaded Videos when loading more fails and retries the same cursor', async () => {
  const user = userEvent.setup();
  const reads = videoResponses(
    () => json({ items: [video(1)], nextCursor: '0123456789abcdef01234567' }),
    () => json({ message: 'Unavailable' }, 503),
    () => json({ items: [video(2)], nextCursor: null })
  );
  renderVideos();
  await user.click(await screen.findByRole('button', { name: 'Load more' }));

  expect(await screen.findByRole('alert')).toBeInTheDocument();
  expect(screen.getByRole('button', { name: /Lorem Video 1/ })).toBeInTheDocument();
  await user.click(screen.getByRole('button', { name: 'Load more' }));

  expect(await screen.findByRole('button', { name: /Lorem Video 2/ })).toBeInTheDocument();
  expect(reads[2]).toBe(reads[1]);
  expect(screen.queryByRole('alert')).not.toBeInTheDocument();
});

test('rejects a malformed mixed Audio and Video response instead of showing Audio cards', async () => {
  videoResponses(() => json({ items: [{ ...video(1), mediaType: 'audio' }], nextCursor: null }));
  renderVideos();

  expect(await screen.findByRole('alert')).toBeInTheDocument();
  expect(screen.queryByRole('button', { name: /Lorem Video 1/ })).not.toBeInTheDocument();
});

test('preserves rendered Videos when refresh fails and explains how to retry', async () => {
  const user = userEvent.setup();
  videoResponses(
    () => json({ items: [video(1)], nextCursor: null }),
    () => json({ message: 'Unavailable' }, 503),
    () => json({ items: [video(2)], nextCursor: null })
  );
  const { queryClient } = renderVideos();
  expect(await screen.findByRole('button', { name: /Lorem Video 1/ })).toBeInTheDocument();
  await act(async () => { await queryClient.refetchQueries({ queryKey: listenerVideosQueryKey }); });
  expect(await screen.findByRole('alert')).toBeInTheDocument();
  expect(screen.getByRole('button', { name: /Lorem Video 1/ })).toBeInTheDocument();
  await user.click(screen.getByRole('button', { name: 'Try again' }));
  expect(await screen.findByRole('button', { name: /Lorem Video 2/ })).toBeInTheDocument();
  expect(screen.queryByRole('button', { name: /Lorem Video 1/ })).not.toBeInTheDocument();
});
